// Simple Asteroid Escape game
// Canvas element with id="game"
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');

// Resize canvas to fill window
function resize() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}
window.addEventListener('resize', resize);
resize();

// Ship object
const ship = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  radius: 10,
  speed: 4,
  angle: 0,
};

// Input handling
const keys = {};
window.addEventListener('keydown', e => { keys[e.key] = true; });
window.addEventListener('keyup', e => { keys[e.key] = false; });

function updateShip() {
  if (keys.ArrowUp || keys.w) ship.y -= ship.speed;
  if (keys.ArrowDown || keys.s) ship.y += ship.speed;
  if (keys.ArrowLeft || keys.a) ship.x -= ship.speed;
  if (keys.ArrowRight || keys.d) ship.x += ship.speed;
  // Keep within bounds
  ship.x = Math.max(ship.radius, Math.min(canvas.width - ship.radius, ship.x));
  ship.y = Math.max(ship.radius, Math.min(canvas.height - ship.radius, ship.y));
}

// Asteroid pool
const asteroids = [];
function spawnAsteroid() {
  const edge = Math.floor(Math.random() * 4);
  let x, y, vx, vy;
  const speed = 1 + Math.random() * 2;
  if (edge === 0) { // top
    x = Math.random() * canvas.width; y = -20; vx = (Math.random() - 0.5) * speed; vy = speed;
  } else if (edge === 1) { // bottom
    x = Math.random() * canvas.width; y = canvas.height + 20; vx = (Math.random() - 0.5) * speed; vy = -speed;
  } else if (edge === 2) { // left
    x = -20; y = Math.random() * canvas.height; vx = speed; vy = (Math.random() - 0.5) * speed;
  } else { // right
    x = canvas.width + 20; y = Math.random() * canvas.height; vx = -speed; vy = (Math.random() - 0.5) * speed;
  }
  asteroids.push({x, y, vx, vy, radius: 15 + Math.random() * 10});
}
let spawnTimer = 0;

function updateAsteroids(dt) {
  spawnTimer -= dt;
  if (spawnTimer <= 0) {
    spawnAsteroid();
    spawnTimer = 0.5 + Math.random(); // seconds until next spawn
  }
  for (let i = asteroids.length - 1; i >= 0; i--) {
    const a = asteroids[i];
    a.x += a.vx * dt * 60; // scale by 60fps base
    a.y += a.vy * dt * 60;
    // remove if off-screen
    if (a.x < -30 || a.x > canvas.width + 30 || a.y < -30 || a.y > canvas.height + 30) {
      asteroids.splice(i, 1);
    }
  }
}

function checkCollision() {
  for (const a of asteroids) {
    const dx = ship.x - a.x;
    const dy = ship.y - a.y;
    const dist = Math.hypot(dx, dy);
    if (dist < ship.radius + a.radius) {
      // Game over – stop loop
      cancelAnimationFrame(animId);
      alert('Game Over!');
      return true;
    }
  }
  return false;
}

let lastTime = 0;
let animId;
function loop(timestamp) {
  const dt = (timestamp - lastTime) / 1000; // seconds
  lastTime = timestamp;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  updateShip();
  updateAsteroids(dt);
  // draw ship
  ctx.fillStyle = 'cyan';
  ctx.beginPath();
  ctx.arc(ship.x, ship.y, ship.radius, 0, Math.PI * 2);
  ctx.fill();
  // draw asteroids
  ctx.fillStyle = 'gray';
  for (const a of asteroids) {
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
    ctx.fill();
  }
  if (!checkCollision()) {
    animId = requestAnimationFrame(loop);
  }
}
animId = requestAnimationFrame(loop);

// Simple score based on time survived
let score = 0;
function updateScore(dt) {
  score += dt;
  ctx.fillStyle = 'white';
  ctx.font = '20px sans-serif';
  ctx.fillText('Score: ' + Math.floor(score), 10, 30);
}
// integrate score drawing into loop
function loop(timestamp) {
  const dt = (timestamp - lastTime) / 1000;
  lastTime = timestamp;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  updateShip();
