  ctx.arc(ship.x, ship.y, ship.radius, 0, Math.PI * 2);
  ctx.fill();
  // draw asteroids
  ctx.fillStyle = 'gray';
  for (const a of asteroids) {
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
    ctx.fill();
  }
  updateScore(dt);
  if (!checkCollision()) {
    animId = requestAnimationFrame(loop);
  }
}
